To convert a Flutter `CameraImage` to PNG, you usually need to:

1. Convert the raw camera format, commonly `YUV_420_888` on Android, to RGB.
2. Create an `image.Image`.
3. Encode it as PNG bytes.

Add the `image` package:

```yaml
dependencies:
  image: ^4.1.7
```

Then you can use this helper:

```dart
import 'dart:typed_data';
import 'package:camera/camera.dart';
import 'package:image/image.dart' as img;

Uint8List cameraImageToPng(CameraImage image) {
  final img.Image convertedImage = _convertYUV420ToImage(image);
  return Uint8List.fromList(img.encodePng(convertedImage));
}

img.Image _convertYUV420ToImage(CameraImage image) {
  final int width = image.width;
  final int height = image.height;

  final img.Image imgBuffer = img.Image(width: width, height: height);

  final Plane yPlane = image.planes[0];
  final Plane uPlane = image.planes[1];
  final Plane vPlane = image.planes[2];

  final Uint8List yBytes = yPlane.bytes;
  final Uint8List uBytes = uPlane.bytes;
  final Uint8List vBytes = vPlane.bytes;

  final int yRowStride = yPlane.bytesPerRow;
  final int uvRowStride = uPlane.bytesPerRow;
  final int uvPixelStride = uPlane.bytesPerPixel ?? 1;

  for (int y = 0; y < height; y++) {
    for (int x = 0; x < width; x++) {
      final int yIndex = y * yRowStride + x;

      final int uvX = x ~/ 2;
      final int uvY = y ~/ 2;
      final int uvIndex = uvY * uvRowStride + uvX * uvPixelStride;

      final int yp = yBytes[yIndex];
      final int up = uBytes[uvIndex];
      final int vp = vBytes[uvIndex];

      int r = (yp + 1.402 * (vp - 128)).round();
      int g = (yp - 0.344136 * (up - 128) - 0.714136 * (vp - 128)).round();
      int b = (yp + 1.772 * (up - 128)).round();

      r = r.clamp(0, 255);
      g = g.clamp(0, 255);
      b = b.clamp(0, 255);

      imgBuffer.setPixelRgb(x, y, r, g, b);
    }
  }

  return imgBuffer;
}
```

Usage:

```dart
controller.startImageStream((CameraImage cameraImage) {
  final Uint8List pngBytes = cameraImageToPng(cameraImage);

  // Example: save, upload, or display the PNG bytes
});
```

If you want to save it to a file:

```dart
import 'dart:io';
import 'package:path_provider/path_provider.dart';

Future<File> saveCameraImageAsPng(CameraImage cameraImage) async {
  final Uint8List pngBytes = cameraImageToPng(cameraImage);

  final directory = await getTemporaryDirectory();
  final file = File('${directory.path}/camera_image.png');

  return file.writeAsBytes(pngBytes);
}
```

On iOS, the camera may provide `bgra8888` instead of YUV. For that case, use this:

```dart
Uint8List cameraImageToPngCrossPlatform(CameraImage image) {
  if (image.format.group == ImageFormatGroup.bgra8888) {
    final img.Image convertedImage = _convertBGRA8888ToImage(image);
    return Uint8List.fromList(img.encodePng(convertedImage));
  } else if (image.format.group == ImageFormatGroup.yuv420) {
    final img.Image convertedImage = _convertYUV420ToImage(image);
    return Uint8List.fromList(img.encodePng(convertedImage));
  } else {
    throw UnsupportedError('Unsupported image format: ${image.format.group}');
  }
}

img.Image _convertBGRA8888ToImage(CameraImage image) {
  final int width = image.width;
  final int height = image.height;
  final Plane plane = image.planes[0];

  final img.Image imgBuffer = img.Image(width: width, height: height);

  final Uint8List bytes = plane.bytes;
  final int bytesPerRow = plane.bytesPerRow;

  for (int y = 0; y < height; y++) {
    for (int x = 0; x < width; x++) {
      final int index = y * bytesPerRow + x * 4;

      final int b = bytes[index];
      final int g = bytes[index + 1];
      final int r = bytes[index + 2];

      imgBuffer.setPixelRgb(x, y, r, g, b);
    }
  }

  return imgBuffer;
}
```

Then call:

```dart
final Uint8List pngBytes = cameraImageToPngCrossPlatform(cameraImage);
```

Note: converting every camera frame to PNG is slow. If you are doing this inside `startImageStream`, consider processing only one frame at a time or moving the conversion to an isolate.

